package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func assuranceEmit(t *testing.T, fields map[string]interface{}) {
	b, err := json.Marshal(fields)
	if err != nil {
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

// TestAssurance_AddVoterConfigVisibility observes, for a stable two-voter
// cluster, whether the configuration entry appended by AddVoter becomes
// visible in the configuration reported by the pre-existing voters, and how
// long any disagreement lasts. The new server is a real, unbootstrapped
// raft instance merged into the same in-process network.
func TestAssurance_AddVoterConfigVisibility(t *testing.T) {
	c := MakeCluster(2, t, nil)
	defer c.Close()

	c1 := MakeClusterNoBootstrap(1, t, nil)
	defer c1.Close()

	c.Merge(c1)
	c.FullyConnect()

	leader := c.Leader()
	newNode := c1.rafts[0]

	assuranceEmit(t, map[string]interface{}{
		"event":     "setup",
		"leader_id": string(leader.localID),
		"new_id":    string(newNode.localID),
	})

	start := time.Now()
	future := leader.AddVoter(newNode.localID, newNode.localAddr, 0, 0)
	err := future.Error()
	assuranceEmit(t, map[string]interface{}{
		"event":      "addvoter_result",
		"elapsed_ms": time.Since(start).Milliseconds(),
		"err":        fmt.Sprintf("%v", err),
		"index":      future.Index(),
	})

	deadline := time.Now().Add(3 * time.Second)
	probe := 0
	for time.Now().Before(deadline) {
		for _, r := range c.rafts {
			cfg := c.getConfiguration(r)
			voters := 0
			for _, s := range cfg.Servers {
				if s.Suffrage == Voter {
					voters++
				}
			}
			assuranceEmit(t, map[string]interface{}{
				"event":          "config_sample",
				"probe":          probe,
				"elapsed_ms":     time.Since(start).Milliseconds(),
				"peer_id":        string(r.localID),
				"is_new_node":    string(r.localID) == string(newNode.localID),
				"num_servers":    len(cfg.Servers),
				"num_voters":     voters,
				"has_new_member": inConfiguration(cfg, newNode.localID),
			})
		}
		probe++
		time.Sleep(100 * time.Millisecond)
	}
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func assuranceEmit(t *testing.T, fields map[string]interface{}) {
	b, err := json.Marshal(fields)
	if err != nil {
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

// boundedApply enqueues cmd on the leader and reports whether the apply future
// completed inside window. It never blocks the test past the window.
func boundedApply(leader *Raft, cmd string, window time.Duration) (committed bool, err error) {
	future := leader.Apply([]byte(cmd), window)
	done := make(chan error, 1)
	go func() { done <- future.Error() }()
	select {
	case e := <-done:
		return true, e
	case <-time.After(window):
		return false, nil
	}
}

// TestAssurance_NonvoterCommitEligibility checks whether a nonvoter's
// acknowledgement can advance the leader's commit index. The cluster is two
// Voters (quorum 2) plus one real Nonvoter that is fully caught up. Withholding
// the nonvoter must not affect commitment; withholding a voter must stall it
// even though the nonvoter keeps storing entries.
func TestAssurance_NonvoterCommitEligibility(t *testing.T) {
	c := MakeCluster(2, t, nil)
	defer c.Close()

	c1 := MakeClusterNoBootstrap(1, t, nil)
	defer c1.Close()

	c.Merge(c1)
	c.FullyConnect()

	leader := c.Leader()
	nonvoter := c1.rafts[0]

	future := leader.AddNonvoter(nonvoter.localID, nonvoter.localAddr, 0, 0)
	err := future.Error()
	assuranceEmit(t, map[string]interface{}{
		"event":             "addnonvoter_result",
		"err":               fmt.Sprintf("%v", err),
		"index":             future.Index(),
		"leader_id":         string(leader.localID),
		"nonvoter_id":       string(nonvoter.localID),
		"nonvoter_addr":     string(nonvoter.localAddr),
		"leader_last_index": leader.getLastIndex(),
		"leader_commit":     leader.getCommitIndex(),
	})

	// Let the new configuration and the nonvoter catch up.
	time.Sleep(300 * time.Millisecond)

	var voterFollower *Raft
	for _, r := range c.rafts {
		if r != leader && r.localID != nonvoter.localID {
			voterFollower = r
		}
	}
	if voterFollower == nil {
		t.Fatalf("no voter follower found")
	}

	assuranceEmit(t, map[string]interface{}{
		"event":              "baseline",
		"leader_commit":      leader.getCommitIndex(),
		"leader_last_index":  leader.getLastIndex(),
		"voter_last_index":   voterFollower.getLastIndex(),
		"nonvoter_last_index": nonvoter.getLastIndex(),
	})

	// Mode A: the Nonvoter is withheld; the two Voters are healthy.
	c.Disconnect(nonvoter.localAddr)
	commitA, errA := boundedApply(leader, "mode-a", 800*time.Millisecond)
	assuranceEmit(t, map[string]interface{}{
		"event":              "mode_a_nv_isolated",
		"committed_in_window": commitA,
		"err":                fmt.Sprintf("%v", errA),
		"leader_last_index":  leader.getLastIndex(),
		"leader_commit":      leader.getCommitIndex(),
		"nonvoter_last_index": nonvoter.getLastIndex(),
	})

	// Reconnect everyone, let the pipeline settle.
	c.FullyConnect()
	time.Sleep(300 * time.Millisecond)

	// Mode B: a Voter is withheld; the Nonvoter is healthy and can store logs.
	c.Disconnect(voterFollower.localAddr)
	beforeLast := leader.getLastIndex()
	commitB, errB := boundedApply(leader, "mode-b", 800*time.Millisecond)
	leaderLast := leader.getLastIndex()
	leaderCommit := leader.getCommitIndex()
	time.Sleep(300 * time.Millisecond)
	assuranceEmit(t, map[string]interface{}{
		"event":               "mode_b_voter_isolated",
		"committed_in_window": commitB,
		"err":                 fmt.Sprintf("%v", errB),
		"leader_last_before":  beforeLast,
		"leader_last_index":   leaderLast,
		"leader_commit":       leaderCommit,
		"nonvoter_last_index": nonvoter.getLastIndex(),
		"nonvoter_has_entry":  nonvoter.getLastIndex() >= leaderLast,
	})
}

package raft

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func assuranceEmit(t *testing.T, fields map[string]interface{}) {
	b, err := json.Marshal(fields)
	if err != nil {
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

// assuranceVote sends a real RequestVote RPC to target from sender and returns
// the granted flag actually reported by the target.
func assuranceVote(sender, target *Raft, candidate *Raft, term uint64) bool {
	idx, t := target.getLastEntry()
	req := &RequestVoteRequest{
		RPCHeader: RPCHeader{
			ProtocolVersion: 3,
			ID:              []byte(candidate.localID),
			Addr:            sender.trans.EncodePeer(candidate.localID, candidate.localAddr),
		},
		Term:               term,
		Candidate:          sender.trans.EncodePeer(candidate.localID, candidate.localAddr),
		LastLogIndex:       idx,
		LastLogTerm:        t,
		LeadershipTransfer: true,
	}
	resp := &RequestVoteResponse{}
	if err := sender.trans.RequestVote(target.localID, target.localAddr, req, resp); err != nil {
		return false
	}
	return resp.Granted
}

// TestAssurance_VoteDurabilityAcrossRestart checks that a node reuses its
// durable last vote after a restart: a second, different candidate in the same
// term must be denied while the original candidate is still granted.
func TestAssurance_VoteDurabilityAcrossRestart(t *testing.T) {
	c := MakeCluster(3, t, nil)
	defer c.Close()

	sender := c.rafts[0]
	target := c.rafts[2]
	candA := c.rafts[1]
	candB := c.rafts[0]

	term := target.getCurrentTerm() + 5

	grantedA1 := assuranceVote(sender, target, candA, term)
	storedTerm, _ := target.stable.GetUint64(keyLastVoteTerm)
	storedCand, _ := target.stable.Get(keyLastVoteCand)
	assuranceEmit(t, map[string]interface{}{
		"event":            "before_restart_vote_a",
		"term":             term,
		"granted":          grantedA1,
		"stored_term":      storedTerm,
		"stored_cand":      string(storedCand),
		"candidate_a":      string(candA.localID),
		"target_term_after": target.getCurrentTerm(),
	})

	// Restart the target over the same stores and transport.
	if err := target.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	confCopy := *c.conf
	confCopy.LocalID = target.localID
	restarted, err := NewRaft(&confCopy, c.fsms[2], c.stores[2], c.stores[2], c.snaps[2], c.trans[2])
	if err != nil {
		t.Fatalf("restart: %v", err)
	}
	defer restarted.Shutdown()
	time.Sleep(200 * time.Millisecond)

	dupTerm, _ := restarted.stable.GetUint64(keyLastVoteTerm)
	dupCand, _ := restarted.stable.Get(keyLastVoteCand)
	assuranceEmit(t, map[string]interface{}{
		"event":              "after_restart_baseline",
		"restored_term":      restarted.getCurrentTerm(),
		"restored_vote_term": dupTerm,
		"restored_vote_cand": string(dupCand),
	})

	grantedA2 := assuranceVote(sender, restarted, candA, term)
	grantedB := assuranceVote(sender, restarted, candB, term)
	grantedOld := assuranceVote(sender, restarted, candB, term-1)

	assuranceEmit(t, map[string]interface{}{
		"event":             "after_restart_votes",
		"term":              term,
		"granted_same_cand": grantedA2,
		"granted_other_cand": grantedB,
		"granted_older_term": grantedOld,
	})
}

